def calcans(s, dest, r, g, b):
	rc = 0
	gc = 0
	bc = 0
	ans = 0
	for i in range(len(s)):
		if s[i] == 'r':
			rc += 1
			if g < r:
				ans += gc
			if b < r:
				ans += bc
		if s[i] == 'b':
			bc += 1
			if g < b:
				ans += gc
			if r < b:
				ans += rc
		if s[i] == 'g':
			gc += 1
			if b < g:
				ans += bc
			if r < g:
				ans += rc
	return ans
for _ in range(int(input())):
	s = input()
	gcount = s.count('g')
	rcount = s.count('r')
	bcount = s.count('b')
	ss = [('r' * rcount + 'g' * gcount + 'b' * bcount, 0, 1, 2), ('r' * rcount + 'b' * bcount + 'g' * gcount, 0, 2, 1), ('g' * gcount + 'b' * bcount + 'r' * rcount, 2, 0, 1), ('g' * gcount + 'r' * rcount + 'b' * bcount, 1, 0, 2), ('b' * bcount + 'r' * rcount + 'g' * gcount, 1, 2, 0), ('b' * bcount + 'g' * gcount + 'r' * rcount, 2, 1, 0)]
	ans = float('inf')
	for (des, r, g, b) in ss:
		ans = min(ans, calcans(s, des, r, g, b))
	print(ans)
